        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

contracts/BinaryTrophyNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";

/// @title BinaryTrophyNFT — max 10 supply, 10% royalties (EIP-2981), on-chain SVG+stats metadata + revenue pot.
contract BinaryTrophyNFT is ERC721, ERC2981, Ownable {
    uint256 public constant MAX_SUPPLY = 10;
    uint96 public constant ROYALTY_BPS = 1000; // 10%

    uint256 private _nextId = 1;
    mapping(uint256 => uint64) public totalClicks;
    mapping(uint256 => uint8) public cipherFragmentSlot;
    mapping(address => uint256) public pendingEth;

    error TrophyCap();
    error TrophyZeroAddr();

    constructor(address initialOwner, address royaltyReceiver)
        ERC721("ClickMint Binary Trophy", "BTROPHY")
        Ownable(initialOwner)
    {
        if (royaltyReceiver == address(0)) revert TrophyZeroAddr();
        _setDefaultRoyalty(royaltyReceiver, ROYALTY_BPS);
    }

    function supportsInterface(bytes4 iid) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(iid);
    }

    /// @notice MVP mint path — owner mints testnet supply (10).
    function mint(address to, uint64 clicks, uint8 fragmentSlot) external onlyOwner {
        uint256 id = _nextId;
        if (id > MAX_SUPPLY) revert TrophyCap();
        _nextId = id + 1;
        totalClicks[id] = clicks;
        cipherFragmentSlot[id] = fragmentSlot;
        _safeMint(to, id);
    }

    receive() external payable {
        uint256 n = _nextId - 1;
        if (n == 0 || msg.value == 0) return;
        uint256 each = msg.value / n;
        unchecked {
            for (uint256 t = 1; t <= n; ++t) {
                address h = _ownerOf(t);
                if (h != address(0)) pendingEth[h] += each;
            }
        }
        uint256 rem = msg.value - each * n;
        if (rem > 0) {
            address h0 = _ownerOf(1);
            if (h0 != address(0)) pendingEth[h0] += rem;
        }
    }

    function claimRevenue() external {
        uint256 amt = pendingEth[msg.sender];
        if (amt == 0) return;
        pendingEth[msg.sender] = 0;
        (bool ok,) = payable(msg.sender).call{value: amt}("");
        require(ok, "trophy: eth");
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        string memory svg = _buildSvg(tokenId);
        string memory json = string.concat(
            '{"name":"Binary Trophy #',
            Strings.toString(tokenId),
            '","description":"ClickMint Phase 1 - revenue-share trophy with on-chain stats + cipher fragment slot.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(svg)),
            '","attributes":[{"trait_type":"Total Clicks","value":',
            Strings.toString(totalClicks[tokenId]),
            '},{"trait_type":"Cipher Fragment","value":',
            Strings.toString(uint256(cipherFragmentSlot[tokenId])),
            "}]}"
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    function _buildSvg(uint256 tokenId) internal view returns (string memory) {
        // Minimal neon cyberpunk trophy — all on-chain, no external URLs.
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512">',
            '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">',
            '<stop offset="0" stop-color="#00ffd5"/><stop offset="1" stop-color="#bd00ff"/></linearGradient></defs>',
            '<rect width="512" height="512" fill="#0b0f14"/>',
            '<text x="48" y="80" fill="#00ffd5" font-size="28" font-family="monospace">CLICKMINT</text>',
            '<text x="48" y="120" fill="#9ae6ff" font-size="18" font-family="monospace">BT #',
            Strings.toString(tokenId),
            "</text>",
            '<path fill="url(#g)" d="M160 140h192l-32 210h-128z"/>',
            '<rect x="196" y="100" width="120" height="40" rx="8" fill="#141c24" stroke="#00ffd5" stroke-width="4"/>',
            '<text x="220" y="128" fill="#e6f7ff" font-size="14" font-family="monospace">',
            Strings.toString(totalClicks[tokenId]),
            ' CLK</text>',
            '<text x="48" y="420" fill="#bd00ff" font-size="16" font-family="monospace">FRAG ',
            Strings.toString(uint256(cipherFragmentSlot[tokenId])),
            "</text>",
            "</svg>"
        );
    }
}

contracts/CLICK.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title CLICK — capped supply, 1% transfer tax, vested “pending” rewards + 30/30/20/20 early spend.
/// @dev Testnet: 1M max supply, 10-minute vesting (production: 7 days).
contract CLICK is ERC20, ERC20Permit, Ownable {
    uint256 public constant MAX_SUPPLY = 1_000_000 ether;
    uint256 public constant BPS = 10_000;
    uint256 public constant TRANSFER_TAX_BPS = 100; // 1%
    uint256 public constant EARLY_BURN_BPS = 3_000;
    uint256 public constant EARLY_TREASURY_BPS = 3_000;
    uint256 public constant EARLY_LP_BPS = 2_000;
    uint256 public constant EARLY_USER_BPS = 2_000;

    address public game;
    address public treasury;
    address public lpRecipient;

    uint256 public vestingDuration;

    struct Vault {
        uint256 total;
        uint256 claimed;
        uint64 start;
    }

    mapping(address account => Vault) internal _vault;

    error CLICKUnauthorized();
    error CLICKCap();
    error CLICKZeroAddr();

    modifier onlyGame() {
        if (msg.sender != game) revert CLICKUnauthorized();
        _;
    }

    constructor(
        address initialOwner,
        address treasury_,
        address lpRecipient_,
        uint256 vestingDuration_
    ) ERC20("ClickMint", "CLICK") ERC20Permit("ClickMint") Ownable(initialOwner) {
        if (treasury_ == address(0) || lpRecipient_ == address(0)) revert CLICKZeroAddr();
        treasury = treasury_;
        lpRecipient = lpRecipient_;
        vestingDuration = vestingDuration_;
    }

    function setGame(address game_) external onlyOwner {
        if (game_ == address(0)) revert CLICKZeroAddr();
        game = game_;
    }

    function setTreasury(address t) external onlyOwner {
        if (t == address(0)) revert CLICKZeroAddr();
        treasury = t;
    }

    function setLpRecipient(address lp) external onlyOwner {
        if (lp == address(0)) revert CLICKZeroAddr();
        lpRecipient = lp;
    }

    function setVestingDuration(uint256 seconds_) external onlyOwner {
        vestingDuration = seconds_;
    }

    /// @notice Grant vesting CLICK from gameplay; any instant unlock from sync is minted here (cap-checked).
    function grantVested(address to, uint256 amount) external onlyGame {
        if (amount == 0) return;
        _syncAndGrant(to, amount);
        if (totalSupply() > MAX_SUPPLY) revert CLICKCap();
    }

    function pendingVested(address account) external view returns (uint256 unvested) {
        Vault memory v = _vault[account];
        uint256 vtd = _vested(v);
        if (v.total > vtd) unvested = v.total - vtd;
    }

    function claimable(address account) external view returns (uint256) {
        Vault memory v = _vault[account];
        return _vested(v) - v.claimed;
    }

    /// @notice Release linearly vested CLICK to liquid balance.
    function claimVested() external {
        Vault storage v = _vault[msg.sender];
        uint256 vested = _vested(v);
        uint256 rel = vested - v.claimed;
        if (rel == 0) return;
        v.claimed = vested;
        _mint(msg.sender, rel);
        require(totalSupply() <= MAX_SUPPLY, "click: cap");
    }

    /// @notice Early liquidate unvested pending with protocol split (30/30/20/20).
    function earlySpendPending(uint256 amount) external {
        Vault storage v = _vault[msg.sender];
        uint256 vested = _vested(v);
        uint256 unvested = v.total > vested ? v.total - vested : 0;
        require(amount <= unvested, "click: unvested");
        v.total -= amount;

        uint256 burnAmt = amount * EARLY_BURN_BPS / BPS;
        uint256 toTreasury = amount * EARLY_TREASURY_BPS / BPS;
        uint256 toLp = amount * EARLY_LP_BPS / BPS;
        uint256 toUser = amount - burnAmt - toTreasury - toLp;

        if (burnAmt > 0) _mint(address(0xdead), burnAmt);
        if (toTreasury > 0) _mint(treasury, toTreasury);
        if (toLp > 0) _mint(lpRecipient, toLp);
        if (toUser > 0) _mint(msg.sender, toUser);
        require(totalSupply() <= MAX_SUPPLY, "click: cap");
    }

    function _vested(Vault memory v) internal view returns (uint256) {
        if (v.total == 0 || v.start == 0) return 0;
        if (vestingDuration == 0) return v.total;
        if (block.timestamp >= v.start + vestingDuration) return v.total;
        return (v.total * (block.timestamp - v.start)) / vestingDuration;
    }

    function _syncAndGrant(address to, uint256 amount) internal {
        Vault storage v = _vault[to];
        uint256 vested = _vested(v);
        uint256 rel = vested - v.claimed;
        if (rel > 0) {
            v.claimed = vested;
            _mint(to, rel);
        }
        uint256 unvested = v.total > vested ? v.total - vested : 0;
        v.total = unvested + amount;
        v.start = uint64(block.timestamp);
        v.claimed = 0;
    }

    function _update(address from, address to, uint256 value) internal override {
        if (from != address(0) && to != address(0) && TRANSFER_TAX_BPS > 0) {
            uint256 tax = (value * TRANSFER_TAX_BPS) / BPS;
            if (tax > 0) {
                super._update(from, treasury, tax);
                value -= tax;
            }
        }
        super._update(from, to, value);
    }

    /// @dev Optional direct mint for POT / ops (game only), still respects cap at call sites.
    function mint(address to, uint256 amount) external onlyGame {
        _mint(to, amount);
        require(totalSupply() <= MAX_SUPPLY, "click: cap");
    }
}

contracts/ClickMintGame.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {CLICK} from "./CLICK.sol";

/// @title ClickMintGame — ETH credits, fee split, rate-limited clicks, hourly CLICK POT (testnet-tuned).
/// @dev Randomness: block.prevrandao + salt — upgrade to Chainlink VRF for mainnet fairness.
contract ClickMintGame is Ownable, ReentrancyGuard {
    CLICK public immutable clickToken;

    address payable public treasury;
    address payable public secretWallet;

    /// @notice ~20s after each UTC hour boundary before the next game hour ticks (reset buffer).
    uint256 public constant RESET_BUFFER = 20;
    uint256 public constant BPS = 10_000;
    /// @dev 3% total: 1% treasury / 1% pot (ETH) / 1% secret. Credits are still granted on full `msg.value`.
    uint256 public constant FEE_EACH_BPS = 100;

    uint256 public constant MIN_POT_CLICKS = 100;
    uint256 public constant MAX_CLICKS_PER_BLOCK = 2;

    /// @notice Wei of CLICK minted per 1 ETH of pot (scaled — testnet sized).
    uint256 public clickPerEthWei;

    uint256 public clickCostCredits;
    uint256 public baseClickReward;

    /// @notice Last pot settlement (game hour id).
    mapping(uint256 hourId => bool) public hourFinalized;
    mapping(uint256 hourId => address) public hourWinner;
    mapping(uint256 hourId => uint256) public hourPayout;
    mapping(uint256 hourId => uint8) public hourWinWindow;

    mapping(address => uint256) public credits;
    mapping(uint256 hourId => mapping(address => uint256)) public clicksInHour;
    mapping(uint256 hourId => mapping(address => uint8)) public windowMask;
    mapping(uint256 hourId => mapping(address => bool)) internal _hourListed;
    mapping(uint256 hourId => address[]) internal _participants;

    /// @notice ETH (wei) reserved for POT for a specific game hour (1% fee slice on deposits).
    mapping(uint256 hourId => uint256) public potEthByHour;
    /// @notice Rolled-forward POT ETH when an hour finalizes with no eligible winner.
    uint256 public potCarry;
    uint256 internal _potNonce;

    mapping(address => mapping(uint256 => uint8)) internal _clicksInBlock;

    event Deposited(address indexed user, uint256 ethIn, uint256 creditsOut);
    event Clicked(address indexed user, uint256 hourId, uint256 totalForUserHour, uint8 window);
    event PotWin(uint256 indexed hourId, address indexed winner, uint256 clickPayout, uint8 window, bytes32 entropy);
    event AddressesUpdated(address treasury, address secret);

    error GameBadAddr();
    error GameCooldown();
    error GameCredits();
    error GameFinalizeEarly();
    error GameAlreadyFinalized();

    constructor(
        address initialOwner,
        CLICK click_,
        address payable treasury_,
        address payable secretWallet_,
        uint256 clickPerEthWei_,
        uint256 clickCostCredits_,
        uint256 baseClickReward_
    ) Ownable(initialOwner) {
        if (address(click_) == address(0)) revert GameBadAddr();
        clickToken = click_;
        treasury = treasury_;
        secretWallet = secretWallet_;
        clickPerEthWei = clickPerEthWei_;
        clickCostCredits = clickCostCredits_;
        baseClickReward = baseClickReward_;
    }

    function setAddresses(address payable treasury_, address payable secretWallet_) external onlyOwner {
        treasury = treasury_;
        secretWallet = secretWallet_;
        emit AddressesUpdated(treasury_, secretWallet_);
    }

    function setEconomy(uint256 clickPerEthWei_, uint256 clickCostCredits_, uint256 baseClickReward_) external onlyOwner {
        clickPerEthWei = clickPerEthWei_;
        clickCostCredits = clickCostCredits_;
        baseClickReward = baseClickReward_;
    }

    function gameHour(uint256 ts) public pure returns (uint256) {
        if (ts <= RESET_BUFFER) return 0;
        return (ts - RESET_BUFFER) / 3600;
    }

    /// @dev Calendar minute 0..59 within the UTC hour.
    function _minuteInUtcHour(uint256 ts) internal pure returns (uint256) {
        return (ts % 3600) / 60;
    }

    /// @dev 15-minute window index 0..3 within the UTC hour — used for POT eligibility.
    function utcWindow(uint256 ts) public pure returns (uint8) {
        return uint8(_minuteInUtcHour(ts) / 15);
    }

    /// @notice Split fees, grant full credits (wei), accrue POT in ETH.
    function deposit() external payable nonReentrant {
        uint256 v = msg.value;
        require(v > 0, "game: eth");
        uint256 ft = (v * FEE_EACH_BPS) / BPS;
        uint256 fp = (v * FEE_EACH_BPS) / BPS;
        uint256 fs = (v * FEE_EACH_BPS) / BPS;
        uint256 fees = ft + fp + fs;
        require(fees <= v, "game: fee");

        (bool okT,) = treasury.call{value: ft}("");
        (bool okS,) = secretWallet.call{value: fs}("");
        require(okT && okS, "game: fee send");

        credits[msg.sender] += v;

        uint256 hid = gameHour(block.timestamp);
        potEthByHour[hid] += fp;

        emit Deposited(msg.sender, v, v);
    }

    /// @notice One click: consumes credits, 2 per block max, records hourly stats + window activity.
    function click() external nonReentrant {
        uint256 cost = clickCostCredits;
        if (cost > 0) {
            if (credits[msg.sender] < cost) revert GameCredits();
            credits[msg.sender] -= cost;
        }

        uint256 bn = block.number;
        if (_clicksInBlock[msg.sender][bn] >= MAX_CLICKS_PER_BLOCK) revert GameCooldown();
        unchecked {
            _clicksInBlock[msg.sender][bn]++;
        }

        uint256 hid = gameHour(block.timestamp);
        uint8 w = utcWindow(block.timestamp);

        uint256 c = clicksInHour[hid][msg.sender] + 1;
        clicksInHour[hid][msg.sender] = c;
        windowMask[hid][msg.sender] |= uint8(1 << w);

        if (!_hourListed[hid][msg.sender]) {
            _hourListed[hid][msg.sender] = true;
            _participants[hid].push(msg.sender);
        }

        emit Clicked(msg.sender, hid, c, w);

        uint256 reward = baseClickReward;
        if (reward > 0) clickToken.grantVested(msg.sender, reward);
    }

    /// @notice After a game hour ends (+ RESET_BUFFER), finalize POT for `hourId`.
    /// @dev Pseudo-random window + winner — acceptable for testnet; VRF for production.
    function finalizeHour(uint256 hourId) external nonReentrant {
        uint256 cutoff = (hourId + 1) * 3600 + RESET_BUFFER;
        if (block.timestamp < cutoff) revert GameFinalizeEarly();
        if (hourFinalized[hourId]) revert GameAlreadyFinalized();

        hourFinalized[hourId] = true;
        _potNonce++;

        bytes32 entropy = keccak256(
            abi.encodePacked(block.prevrandao, hourId, address(this), block.timestamp, _potNonce, block.number)
        );
        uint8 winWindow = uint8(uint256(entropy) % 4);

        address[] storage parts = _participants[hourId];
        address[] memory cand = new address[](parts.length);
        uint256 n = 0;
        for (uint256 i = 0; i < parts.length; ++i) {
            address a = parts[i];
            if (clicksInHour[hourId][a] < MIN_POT_CLICKS) continue;
            if ((windowMask[hourId][a] & uint8(1 << winWindow)) == 0) continue;
            cand[n++] = a;
        }

        hourWinWindow[hourId] = winWindow;

        uint256 pe = potEthByHour[hourId];
        potEthByHour[hourId] = 0;

        if (n == 0) {
            potCarry += pe;
            emit PotWin(hourId, address(0), 0, winWindow, entropy);
            return;
        }

        uint256 gross = pe + potCarry;
        potCarry = 0;

        address winner = cand[uint256(entropy) % n];
        uint256 payout = (gross * clickPerEthWei) / 1 ether;

        hourWinner[hourId] = winner;
        hourPayout[hourId] = payout;

        if (payout > 0) clickToken.mint(winner, payout);

        emit PotWin(hourId, winner, payout, winWindow, entropy);
    }

    function currentPotEth() external view returns (uint256) {
        uint256 hid = gameHour(block.timestamp);
        return potEthByHour[hid] + potCarry;
    }

    /// @notice Owner rescue for rolled POT carry only (does not touch user credit backing ETH).
    function ownerSweepPotCarry(address payable to, uint256 amount) external onlyOwner {
        require(to != address(0), "game: zero");
        require(amount <= potCarry, "game: carry");
        potCarry -= amount;
        (bool ok,) = to.call{value: amount}("");
        require(ok, "game: sweep");
    }

    receive() external payable {}
}

